import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.BPeR9Rpo.js";var o=JSON.parse(`{"title":"Metamodell-Pakete","description":"","frontmatter":{"title":"Metamodell-Pakete","covers":{"screens":[],"stories":["US-033","US-057"]}},"headers":[],"relativePath":"de/administration/metamodel-packages.md","filePath":"de/administration/metamodel-packages.md"}`),s={name:`de/administration/metamodel-packages.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="metamodell-pakete" tabindex="-1">Metamodell-Pakete <a class="header-anchor" href="#metamodell-pakete" aria-label="Permalink to “Metamodell-Pakete”">​</a></h1><p>Eine neue Instanz hat keine Entitätstypen. Bevor jemand Entitäten erfassen kann, importierst du ein Metamodell: das mitgelieferte Starterpaket oder ein eigenes Paket.</p><p>Der Import von Paketen verlangt die Berechtigung <code>metamodel:write</code>, die nur die Rolle <code>metamodel-admin</code> hat – nicht das lokale Systemadmin-Konto. Ordne eine IdP-Gruppe <code>metamodel-admin</code> zu (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>); als privilegierte Rolle braucht sie einen zweiten Faktor beim Identity-Provider.</p><h2 id="starterkonfiguration-importieren" tabindex="-1">Starterkonfiguration importieren <a class="header-anchor" href="#starterkonfiguration-importieren" aria-label="Permalink to “Starterkonfiguration importieren”">​</a></h2><p>OEA liefert das Starterpaket <code>oea-starter-togaf-classic</code> mit den Entitätstypen Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software und Network Node, jeweils mit der Eigenschaft <em>Status</em>. Version 1.4.0 fügt die vier <a href="./metamodel-editing#layers">Schichten</a> <em>Geschäft</em>, <em>Daten</em>, <em>Anwendung</em> und <em>Technologie</em> (englisch <em>Business</em>, <em>Data</em>, <em>Application</em> und <em>Technology</em>) hinzu und ordnet sie den Entitätstypen zu: <em>Application Component</em> und <em>Application Service</em> der Schicht Anwendung, <em>Data Object</em> der Schicht Daten und <em>Technology Component</em>, <em>Technology Service</em>, <em>System Software</em> und <em>Network Node</em> der Schicht Technologie (<em>Komposition</em> hat keine). Der erneute Import in eine Instanz mit einer eigenen Schicht desselben Namens, zum Beispiel <em>Business</em>, wird als Konflikt abgelehnt; benenne diese Schicht zuerst um oder lösche sie. Version 1.3.0 fügt den Verbindungstyp <em>Komposition</em> hinzu, gekennzeichnet als <a href="./metamodel-editing#composition">Komposition</a> der Hierarchie von Komponenten. Version 1.2.0 fügt die zwei systemdefinierten Viewpoints <em>Application Landscape</em> und <em>Technology Landscape</em> in ArchiMate hinzu (siehe <a href="#viewpoints-in-packages">Viewpoints in Paketen</a>). Version 1.1.0 brachte deutsche Labels für seine Entitätstypen, <em>Status</em> und dessen Werte sowie englische Labels für die Werte mit (siehe <a href="./metamodel-editing#translating-labels">Labels übersetzen</a>). Eine Instanz, die eine frühere Version importiert hat, erhält die Labels und Viewpoints durch einen erneuten Import des Pakets.</p><p>Solange die Instanz keinen Entitätstyp hat, zeigt die Startseite einer Person mit <code>metamodel:write</code> den Bereich <em>Startkonfiguration importieren</em>. Wähle <em>Importieren</em> neben dem Paket; die Seite bestätigt, wie viele Entitätstypen jetzt verfügbar sind.</p>`,6),i(d,{name:`starter-import`,alt:`Startseite mit der Starterkonfiguration zum Import`}),o[1]||=t('<p>Über die API:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                    # Liste mit Zusammenfassung</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # importierte Entitätstypen</span></span></code></pre></div><h2 id="eigenes-paket-importieren" tabindex="-1">Eigenes Paket importieren <a class="header-anchor" href="#eigenes-paket-importieren" aria-label="Permalink to “Eigenes Paket importieren”">​</a></h2><p>Eigene Pakete verwenden dasselbe JSON-Format (<code>MetamodelPackage</code>, mit <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> und stabilen UUIDs pro Element). Importiere sie mit <code>POST /metamodel/import</code>:</p><ul><li>Ein Paket wird vollständig oder gar nicht importiert. Importierte Inhalte bekommen den Scope <code>imported</code> und das Paket als Herkunft.</li><li>Ein erneuter Import desselben Pakets aktualisiert dessen eigene Inhalte. Inhalte eines anderen Pakets oder deiner Organisation werden nie überschrieben; die Antwort ist <code>409</code> mit dem Problemtyp <code>urn:oea:problem:package-conflict</code> und der Liste der Konflikte in <code>conflictList</code>, und nichts vom Paket wird gespeichert.</li><li>Ein Paket kann für einen Entitätstyp einen Basistyp nennen (<code>baseMetatypeId</code>): einen Entitätstyp desselben Pakets oder einen eingebauten. Deine eigenen Eigenschaften an seinen Entitätstypen bleiben oder werden entfernt, je nach Einstellung für den erneuten Import (siehe <a href="./metamodel-editing">Metamodell bearbeiten</a>).</li><li>Pakete, die größer als <code>oea.metamodel.import.max-size</code> sind (Standard 10 MB), werden mit <code>413</code> abgelehnt; fehlerhaftes JSON oder Inhalte, die nicht zum Format passen, mit <code>422</code> und der Stelle des Problems.</li><li>Ein Paket kann in <code>i18nBundles</code> Labels pro Sprache mitbringen, mit Schlüsseln wie unter <a href="./metamodel-editing#translating-labels">Labels übersetzen</a>, aber nur für seine eigenen Elemente. Ein erneuter Import ersetzt sie; deine eigenen Labels bleiben.</li><li>Die Strategie <code>replace</code> und Shape-Zuordnungen werden noch nicht unterstützt (<code>422</code>).</li></ul><p>Jeder Import schreibt die Audit-Events <code>metamodel.package-imported</code> und <code>metamodel.metatype-imported</code> mit einer gemeinsamen Batch-ID.</p><h2 id="composition-in-packages" tabindex="-1">Komposition in Paketen <a class="header-anchor" href="#composition-in-packages" aria-label="Permalink to “Komposition in Paketen”">​</a></h2><p>Ein Verbindungstyp eines Pakets kann <code>isComposition: true</code> tragen; ein Paket hat höchstens einen. Der Import wird abgelehnt, wenn die Instanz bereits einen anderen gekennzeichneten Verbindungstyp hat. Ein erneuter Import desselben Pakets verschiebt oder entfernt die Kennzeichnung mit dem Paket.</p><h2 id="layers-in-packages" tabindex="-1">Schichten in Paketen <a class="header-anchor" href="#layers-in-packages" aria-label="Permalink to “Schichten in Paketen”">​</a></h2><p>Ein Paket kann in <code>architectureLayers</code> Architekturschichten mitbringen: jede mit einer stabilen <code>id</code>, einem <code>name</code> mit bis zu 100 Zeichen und einer optionalen <code>sortOrder</code>. Die Entitätstypen des Pakets verweisen mit <code>architectureLayerId</code> darauf. Der Import installiert sie als schreibgeschützte Schichten mit dem Paket als Herkunft (siehe <a href="./metamodel-editing#layers">Schichten</a>).</p><ul><li>Ein Paket hat höchstens 20 Schichten, und zusammen mit den Schichten deiner Organisation hat die Instanz höchstens 20 (sonst <code>422</code>). Namen sind im Paket unabhängig von der Schreibweise eindeutig; ein Entitätstyp, der auf eine Schicht ausserhalb des Pakets verweist, wird mit <code>422</code> abgelehnt.</li><li>Eine Schicht, deren ID oder Name zu einer Schicht deiner Organisation oder eines anderen Pakets gehört, ergibt <code>409</code> mit <code>package-conflict</code>, und nichts wird importiert.</li><li>Neue Schichten stehen hinter den vorhandenen, in der Reihenfolge von <code>sortOrder</code>; vorhandene Schichten behalten ihre Position.</li><li>Ein erneuter Import desselben Pakets aktualisiert seine Schichten. Eine Schicht, die die neue Version nicht mehr hat, wird gelöscht, und jeder Entitätstyp, der sie hatte – auch die deiner Organisation –, verliert seine Schicht. Schichten deiner Organisation bleiben.</li><li>Das Importergebnis zählt die angelegten, aktualisierten und gelöschten Schichten (<code>layersCreated</code>, <code>layersUpdated</code>, <code>layersDeleted</code>) und die Entitätstypen, die eine Schicht verloren haben (<code>layerAssignmentsCleared</code>). Labels für eine Schicht stehen in <code>i18nBundles</code> unter dem Schlüssel <code>architecture-layer.{id}.name</code>.</li></ul><h2 id="viewpoints-in-packages" tabindex="-1">Viewpoints in Paketen <a class="header-anchor" href="#viewpoints-in-packages" aria-label="Permalink to “Viewpoints in Paketen”">​</a></h2><p>Ein Paket kann in <code>viewpoints</code> Viewpoints mitbringen: jeden mit einer stabilen <code>id</code>, <code>name</code>, optionaler <code>description</code>, <code>notation</code>, den erlaubten <code>metatypeIds</code> und <code>connectionTypeIds</code> (Typen des Pakets oder der Instanz), optionalen <code>mappings</code> und optionalen Standardgrössen <code>sizes</code> in pt (<code>metatypeId</code> mit <code>width</code> und <code>height</code> oder <code>length</code>; siehe <a href="./metamodel-editing#viewpoints">Viewpoints</a>). Der Import installiert sie als systemdefinierte, schreibgeschützte Viewpoints mit dem Paket als Herkunft (siehe <a href="./metamodel-editing#viewpoints">Viewpoints</a>).</p><ul><li>Ein Viewpoint hat dieselben Grenzen wie ein eigener: Name bis 255 Zeichen, Beschreibung bis 1000, höchstens 500 Entitätstypen, 500 Verbindungstypen, 1000 Zuordnungen und 1000 Grössen, Grössen von 1 bis 2000 pt und Farben als <code>#rrggbb</code>. Ein Verstoss oder ein unbekannter Typ wird mit <code>422</code> abgelehnt und nennt den Viewpoint, eine fehlerhafte Grösse auch <code>sizes</code>. <code>defaultWidth</code> und <code>defaultHeight</code> in einer Zuordnung werden ignoriert.</li><li>Ein erneuter Import desselben Pakets aktualisiert seine Viewpoints, auch wenn einer umbenannt wurde, und löscht die, die das Paket nicht mehr enthält. Viewpoints deiner Organisation oder eines anderen Pakets werden nie überschrieben: Dieselbe ID oder derselbe Name ergibt <code>409</code>.</li><li>Das Importergebnis zählt die angelegten, aktualisierten und gelöschten Viewpoints.</li></ul>',14)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};